var i=245;var a=[{id:`cooking-245-01`,theoryId:245,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why are some ground spices briefly heated in fat during Middle Eastern cooking?`,ua:`Навіщо деякі мелені спеції коротко прогрівають у жирі під час приготування близькосхідних страв?`},explanation:{en:`Brief moderate heating can release aromas; scorching damages flavor.`,ua:`Коротке помірне нагрівання допомагає розкрити аромат; підгоряння погіршує смак.`},options:[{id:`a`,text:{en:`To make spices permanently sterile`,ua:`Щоб зробити спеції назавжди стерильними`}},{id:`b`,text:{en:`To dissolve and release fat-soluble aroma compounds`,ua:`Щоб розкрити жиророзчинні ароматичні сполуки`}},{id:`c`,text:{en:`To remove every allergen from the dish`,ua:`Щоб видалити всі алергени зі страви`}}],answer:{optionIds:[`b`]}},{id:`cooking-245-02`,theoryId:245,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Tahini and sesame should be treated as a possible allergen source.`,ua:`Тахіні та кунжут потрібно розглядати як потенційне джерело алергенів.`},explanation:{en:`Sesame is an important allergen; substitutions should account for guests’ needs.`,ua:`Кунжут є важливим алергеном; заміни слід добирати відповідно до потреб гостей.`},answer:{value:!0}},{id:`cooking-245-03`,theoryId:245,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match common ingredients with their roles.`,ua:`Поєднайте поширені інгредієнти з їхніми ролями.`},explanation:{en:`Ingredients should be understood by function, not just by name.`,ua:`Інгредієнти слід розуміти за функцією, а не лише за назвою.`},leftItems:[{id:`l1`,text:{en:`Tahini`,ua:`Тахіні`}},{id:`l2`,text:{en:`Chickpeas`,ua:`Нут`}},{id:`l3`,text:{en:`Sumac`,ua:`Сумах`}}],rightItems:[{id:`r2`,text:{en:`Legume base for hummus`,ua:`Бобова основа хумусу`}},{id:`r3`,text:{en:`Adds a tart seasoning note`,ua:`Додає кислувату смакову ноту`}},{id:`r1`,text:{en:`Sesame paste that adds fat and body`,ua:`Кунжутна паста, що додає жир і густину`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-245-04`,theoryId:245,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A ground spice mixture starts smoking and smelling bitter. What should the cook do?`,ua:`Суміш мелених спецій починає диміти та гірчити. Що слід зробити?`},explanation:{en:`Burnt spice compounds cannot reliably be rescued by adding sugar.`,ua:`Підгорілі ароматичні сполуки не можна надійно виправити додаванням цукру.`},options:[{id:`a`,text:{en:`Pour water into very hot oil suddenly`,ua:`Різко влити воду в дуже гарячу олію`}},{id:`b`,text:{en:`Remove from heat and restart if badly scorched`,ua:`Зняти з вогню та почати заново, якщо спеції сильно підгоріли`}},{id:`c`,text:{en:`Continue until black`,ua:`Продовжити до почорніння`}}],answer:{optionIds:[`b`]}},{id:`cooking-245-05`,theoryId:245,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which are valid considerations for a hummus-style preparation?`,ua:`Що варто врахувати під час приготування хумусу?`},explanation:{en:`Safety, texture and ingredient functionality all affect the finished dip.`,ua:`Безпечність, текстура й функції інгредієнтів впливають на готовий дип.`},options:[{id:`a`,text:{en:`Check sesame allergy requirements`,ua:`Перевірити вимоги щодо алергії на кунжут`}},{id:`b`,text:{en:`Assume boiling lemon juice removes sesame proteins`,ua:`Вважати, що кип’ятіння лимонного соку видаляє білки кунжуту`}},{id:`c`,text:{en:`Cook chickpeas appropriately`,ua:`Належно приготувати нут`}},{id:`d`,text:{en:`Adjust liquid and processing for texture`,ua:`Регулювати рідину та подрібнення для потрібної текстури`}}],answer:{optionIds:[`c`,`a`,`d`]}}];var n={theoryId:245,exercises:a};export{n as default,a as exercises,i as theoryId};